package lk.medichannel.auth;
import jakarta.servlet.http.*; import lk.medichannel.audit.AuditService; import lk.medichannel.crypto.CryptoService; import lk.medichannel.security.*; import lk.medichannel.user.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseCookie; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service @Transactional public class AuthService {
 private final UserRepository users; private final CryptoService crypto; private final PasswordEncoder passwords; private final JwtService jwt; private final AuditService audit; private final String cookieName; private final boolean secure; private final int lockThreshold; private final int lockMinutes;
 public AuthService(UserRepository users,CryptoService crypto,PasswordEncoder passwords,JwtService jwt,AuditService audit,@Value("${app.auth.cookie-name:medichannel_token}") String cookieName,@Value("${app.auth.secure-cookie:false}") boolean secure,@Value("${app.auth.lockout-threshold:5}") int lockThreshold,@Value("${app.auth.lockout-minutes:15}") int lockMinutes){this.users=users;this.crypto=crypto;this.passwords=passwords;this.jwt=jwt;this.audit=audit;this.cookieName=cookieName;this.secure=secure;this.lockThreshold=lockThreshold;this.lockMinutes=lockMinutes;}
 public AuthDtos.LoginResponse register(AuthDtos.RegisterRequest request,HttpServletRequest http,HttpServletResponse response){String hash=crypto.hmac(request.email());if(users.findByEmailLookupHash(hash).isPresent())throw new IllegalArgumentException("An account already exists for that email");User u=new User();u.setEmailCiphertext(crypto.encrypt(request.email().trim().toLowerCase()));u.setEmailLookupHash(hash);u.setPasswordHash(passwords.encode(request.password()));u.setRole(UserRole.CUSTOMER);users.save(u);audit.log(u.getId(),"ACCOUNT_REGISTERED","USER",u.getId(),http);setCookie(response,u);return new AuthDtos.LoginResponse(toResponse(u));}
 public AuthDtos.LoginResponse login(AuthDtos.LoginRequest request,HttpServletRequest http,HttpServletResponse response){User u=users.findByEmailLookupHash(crypto.hmac(request.email())).orElse(null);if(u==null||!passwords.matches(request.password(),u.getPasswordHash())){if(u!=null){fail(u,http);}throw new AuthenticationFailureException();}if(!u.isActive())throw new AuthenticationFailureException();if(u.getLockedUntil()!=null&&u.getLockedUntil().isAfter(Instant.now()))throw new AuthenticationFailureException();u.setFailedLoginAttempts(0);u.setLockedUntil(null);audit.log(u.getId(),"LOGIN_SUCCEEDED","USER",u.getId(),http);setCookie(response,u);return new AuthDtos.LoginResponse(toResponse(u));}
 private void fail(User u,HttpServletRequest http){int failures=u.getFailedLoginAttempts()+1;u.setFailedLoginAttempts(failures);if(failures>=lockThreshold){u.setLockedUntil(Instant.now().plus(Duration.ofMinutes(lockMinutes)));u.setFailedLoginAttempts(0);audit.log(u.getId(),"LOGIN_LOCKED","USER",u.getId(),http);}else audit.log(u.getId(),"LOGIN_FAILED","USER",u.getId(),http);}
 public void logout(HttpServletResponse response){response.addHeader("Set-Cookie",cookie("").maxAge(0).build().toString());SecurityContextHolder.clearContext();}
 public void changePassword(CurrentUser actor,AuthDtos.ChangePasswordRequest request,HttpServletRequest http){User u=users.findById(actor.id()).orElseThrow(()->new IllegalArgumentException("Account not found"));if(!passwords.matches(request.currentPassword(),u.getPasswordHash()))throw new IllegalArgumentException("Current password is incorrect");u.setPasswordHash(passwords.encode(request.newPassword()));u.setPasswordChangeRequired(false);audit.log(u.getId(),"PASSWORD_CHANGED","USER",u.getId(),http);}
 public AuthDtos.UserResponse me(CurrentUser user){return users.findById(user.id()).map(this::toResponse).orElseThrow(()->new IllegalArgumentException("Account not found"));}
 public AuthDtos.UserResponse toResponse(User u){return new AuthDtos.UserResponse(u.getId(),crypto.decrypt(u.getEmailCiphertext()),u.getRole(),u.isActive(),u.isPasswordChangeRequired(),u.getCreatedAt());}
 private void setCookie(HttpServletResponse response,User user){response.addHeader("Set-Cookie",cookie(jwt.create(user)).maxAge(jwt.maxAge()).build().toString());}
 private ResponseCookie.ResponseCookieBuilder cookie(String value){return ResponseCookie.from(cookieName,value).httpOnly(true).secure(secure).sameSite("Lax").path("/");}
}
